  "Приложение и уведомления": "App and notifications",
  "Скрыть блок про установку приложения и уведомления": "Hide the app installation and notifications section",
  "Закрыть": "Close",
  "На Android для надёжной фоновой работы лучше использовать мобильное приложение DPoS Space, а не PWA. Актуальная debug-версия APK:": "On Android, for reliable background operation it is better to use the DPoS Space mobile app rather than the PWA. Current debug APK version:",
  "скачать APK ⟦1⟧": "download APK ⟦1⟧",
  "PWA можно использовать как веб-версию: локальные процессы работают пока приложение/вкладка живы; после полного закрытия работа не обещается.": "The PWA can be used as a web version: local processes run while the app/tab remains open; operation is not guaranteed after it is fully closed.",
