  "Уведомления: ⟦4⟧": "Notifications: ⟦4⟧",
  "Установить приложение": "Install app",
  "Включить локальные уведомления": "Enable local notifications",
  "Это не Web Push и не серверный фон: уведомления приходят от открытого приложения/PWA.": "This is not Web Push or a server background process: notifications come from the open app/PWA.",
  "DPoS Space уведомления включены": "DPoS Space notifications are enabled",
  "Локальные уведомления будут показываться, пока приложение или вкладка работает.": "Local notifications will be shown while the app or tab is running.",
  "Не загрузилась защита аккаунтов. Обновите страницу.": "Account protection failed to load. Refresh the page.",
  "Разблокировать аккаунты": "Unlock accounts",
  "Не удалось открыть хранилище": "Could not open storage",
  "Защитить сохранённые аккаунты": "Protect saved accounts",
  "Разблокировка действует до закрытия или блокировки этой вкладки. Повторно вводить ключи не нужно.": "The vault remains unlocked until this tab is closed or locked. You do not need to enter the keys again.",
  "Данные не удалены. Не очищайте хранилище браузера. Если у вас есть резервная копия, её можно восстановить на другом устройстве.": "No data was deleted. Do not clear browser storage. If you have a backup, it can be restored on another device.",
  "Создайте новый пароль или выберите passkey. Существующие аккаунты и настройки сохранятся; повторно вводить ключи и seed-фразы не нужно.": "Create a new password or choose a passkey. Existing accounts and settings will be preserved; you do not need to re-enter keys or seed phrases.",
  "Пароль аккаунтов": "Account password",
  "Перейти к защите аккаунтов": "Go to account protection",
  "Чтобы пользоваться приложением, сначала настройте защиту сохранённых аккаунтов. До завершения настройки поля «Блокчейн», «Раздел» и «Аккаунт» недоступны. Создайте отдельный пароль или выберите passkey в блоке ниже.": "To use the app, first set up protection for saved accounts. The Blockchain, Section and Account fields are unavailable until setup is complete. Create a separate password or choose a passkey in the section below.",
  "Поля «Блокчейн», «Раздел» и «Аккаунт» недоступны, пока аккаунты заблокированы. Разблокируйте их в блоке ниже.": "The Blockchain, Section and Account fields are unavailable while accounts are locked. Unlock them in the section below.",
  "Поля «Блокчейн», «Раздел» и «Аккаунт» недоступны: не удалось открыть хранилище аккаунтов. Подробности — в блоке ниже. Не очищайте данные приложения.": "The Blockchain, Section and Account fields are unavailable: account storage could not be opened. See the section below for details. Do not clear app data.",
  "Новый пароль для защиты сохранённых аккаунтов — не менее 12 символов": "New password to protect saved accounts — at least 12 characters",
  "Новый пароль аккаунтов — не менее 12 символов": "New accounts password — at least 12 characters",
  "Повторите новый пароль": "Repeat new password",
  "Разблокировать": "Unlock",
  "Защитить и продолжить": "Protect and continue",
  "Разблокировать с passkey": "Unlock with passkey",
  "Использовать passkey": "Use passkey",
  "Сохраните пароль или доступ к passkey. После переноса создайте резервную копию в разделе «Резервное копирование». При потере единственного способа разблокировки доступ к ключам может быть утрачен.": "Save the password or passkey access. After migration, create a backup in the \"Backup\" section. If the only unlock method is lost, access to the keys may be lost.",
  "Если passkey не поддерживает шифрование или системный диалог отменён, выберите пароль. До проверки переноса старые данные не удаляются.": "If the passkey does not support encryption or the system dialog is canceled, choose a password. Old data is not deleted until migration is verified.",
