  "Static-only read-only перенос legacy analytics: старый раздел был набором публичных iframe Yandex DataLens без PHP-вычислений, приватного backend и операций блокчейна.": "Static-only read-only legacy analytics migration: the old section was a set of public Yandex DataLens iframes without PHP calculations, a private backend or blockchain operations.",
  "Эта страница не запрашивает ключи, не готовит транзакции и не выполняет broadcast. Встроенные виджеты загружаются напрямую с публичного домена DataLens; рядом есть обычные ссылки на случай блокировки iframe браузером или политикой доступности.": "This page does not request keys, prepare transactions, or broadcast. Embedded widgets load directly from the public DataLens domain; regular links are provided in case the iframe is blocked by the browser or accessibility policy.",
  "Публичная RPC-альтернатива": "Public RPC alternative",
  "Legacy-аналитика — исторические агрегированные дашборды. Полного индексерного набора из публичной VIZ RPC-ноды не получить одним запросом, но для самостоятельной проверки текущего состояния доступны статические v3-разделы: профиль/кошелёк/история аккаунта через публичные RPC-ноды ⟦1⟧.": "Legacy analytics — historical aggregated dashboards. A complete indexer dataset cannot be obtained from a public VIZ RPC node in one request, but static v3 sections are available for independently checking the current state: profile/wallet/account history through public RPC nodes ⟦1⟧.",
