  "Получить код": "Get code",
  "VIZ awards готовы: award/fixedAward, custom_sequence, beneficiaries, link/url/builder/send и QR payload.": "VIZ awards are ready: award/fixedAward, custom_sequence, beneficiaries, link/url/builder/send, and QR payload.",
  "Токен доната": "Donation token",
  "Включить автонаграду для этого аккаунта": "Enable auto-reward for this account",
  "Regular-ключ: ⟦5⟧.": "Regular key: ⟦5⟧.",
  "Минимальная энергия, %": "Minimum energy, %",
  "сохранён": "saved",
  "не найден или недоступен": "not found or unavailable",
  "VIZ: автонаграда себе": "VIZ: self-award automatically",
  "Сервис не даёт энергии простаивать на 100%: выбранные сохранённые аккаунты периодически награждают сами себя, если энергия выше заданного минимума.": "The service prevents energy from remaining idle at 100%: selected saved accounts periodically reward themselves when their energy exceeds the configured minimum.",
  "Важно:": "Important:",
  "кнопка Start — явное согласие на реальные автоматические VIZ award без подтверждения каждой награды. Используется regular-ключ, сохранённый в разделе «Аккаунты».": "The Start button is explicit consent for real automatic VIZ awards without confirmation of each reward. The regular key saved in the “Accounts” section is used.",
  "Что вводить:": "What to enter:",
  "обычный процент энергии — например 95, 99 или 99.9. Это нижняя граница запаса, а не размер награды. При 95% сервис не будет тратить энергию ниже 95%; при 99% сохранит не меньше 99%; при 99.9% награда возможна только почти при полном запасе. За одну проверку тратится максимум 0.1% энергии и только часть выше выбранной границы. Если энергия равна выбранному порогу или ниже, сервис ничего не отправляет. Внутренние значения 9500 и 9900 вводить не нужно.": "a regular energy percentage—for example, 95, 99, or 99.9. This is the reserve floor, not the reward size. At 95%, the service will not spend energy below 95%; at 99%, it will preserve at least 99%; at 99.9%, a reward is possible only when reserves are nearly full. Each check spends at most 0.1% energy and only part of the amount above the selected floor. If energy equals or is below the selected threshold, the service sends nothing. Do not enter internal values such as 9500 or 9900.",
  "Точный параметр сети: 100% энергии восстанавливается за 432000 секунд. Поэтому 0.1% восстанавливается за 7 минут 12 секунд. Внутри VIZ энергия хранится по шкале 0–10000: 9500 означает 95%, а 9900 — 99%. ⟦0⟧": "Exact network parameter: 100% of energy is restored in 432000 seconds. Therefore, 0.1% is restored in 7 minutes 12 seconds. In VIZ, energy is stored on a 0–10000 scale: 9500 means 95%, and 9900 means 99%. ⟦0⟧",
  "Статус и лента": "Status and feed",
  "Остановлено. Реальных наград без кнопки Start нет.": "Stopped. No real rewards are sent without pressing Start.",
  "В Android-приложении Start включает native foreground worker; на сайте работает active-tab режим.": "In the Android app, Start enables the native foreground worker; on the website, active-tab mode is used.",
  "Web-версия работает, пока открыта страница/PWA; фоновая Android-версия доступна в APK.": "The web version works while the page/PWA is open; the background Android version is available in the APK.",
  "если проверки опаздывают после блокировки экрана, откройте настройки батареи приложения и выберите режим «Без ограничений» / «Не оптимизировать» / «Разрешить работу в фоне». Foreground-уведомление будет тихо обновляться текущим статусом VIZ self-award без звуков.": "if checks are delayed after the screen locks, open the app's battery settings and select “Unrestricted” / “Do not optimize” / “Allow background activity.” The foreground notification will quietly update with the current VIZ self-award status without sounds.",
  "Минимальная энергия для всех аккаунтов, %": "Minimum energy for all accounts, %",
  "Скопировать минимум на все аккаунты": "Copy minimum to all accounts",
  "Запускать автоматически при открытии Android-приложения": "Start automatically when the Android app opens",
  "Если включено, APK при открытии проверит сохранённые настройки и сам запустит native worker для выбранных аккаунтов.": "If enabled, the APK checks the saved settings when opened and automatically starts the native worker for the selected accounts.",
  "Запустить Start": "Start",
  "Остановить Stop": "Stop",
  "Нет сохранённых VIZ-аккаунтов. Откройте раздел «Аккаунты» и добавьте аккаунт с regular-ключом.": "No saved VIZ accounts. Open the “Accounts” section and add an account with a regular key.",
  "Запуск отменён.": "Start canceled.",
  "Выберите хотя бы один VIZ-аккаунт.": "Select at least one VIZ account.",
  "Аккаунт @⟦0⟧ не найден в сохранённых аккаунтах.": "Account @⟦0⟧ was not found among the saved accounts.",
  "Сохранённый regular-ключ @⟦0⟧ не найден в regular authority аккаунта. Обновите ключ в разделе «Аккаунты».": "The saved regular key for @⟦0⟧ was not found in the account's regular authority. Update the key in Accounts.",
  "Android native VIZ self-award включён: ⟦0⟧ аккаунтов. ⟦1⟧": "Android native VIZ self-reward enabled: ⟦0⟧ accounts. ⟦1⟧",
  "SKIP @⟦0⟧: не удалось определить энергию.": "SKIP @⟦0⟧: failed to determine energy.",
