  "аккаунт @⟦0⟧ не найден в сохранённых аккаунтах": "account @⟦0⟧ was not found among saved accounts",
  "Автоматическая self-award операция VIZ: initiator и receiver совпадают.": "Automatic VIZ self-award operation: initiator and receiver are the same.",
  "OK @⟦0⟧: self-award ⟦1⟧%, энергия была ⟦2⟧%, минимум ⟦3⟧%.": "OK @⟦0⟧: self-award ⟦1⟧%, energy was ⟦2⟧%, minimum ⟦3⟧%.",
  "Проверка VIZ self-award завершена: аккаунтов ⟦0⟧, наград отправлено ⟦1⟧. Следующая проверка через 7 минут 12 секунд.": "VIZ self-award check completed: ⟦0⟧ accounts, ⟦1⟧ rewards sent. Next check in 7 minutes 12 seconds.",
