  "SKIP @⟦0⟧ уже голосовал за @⟦1⟧/⟦2⟧.": "SKIP @⟦0⟧ has already voted for @⟦1⟧/⟦2⟧.",
  "@⟦0⟧ уже голосовал за @⟦1⟧/⟦2⟧.": "@⟦0⟧ has already voted for @⟦1⟧/⟦2⟧.",
  "Голосовать @⟦0⟧ за @⟦1⟧/⟦2⟧ с весом ⟦3⟧%?": "Vote as @⟦0⟧ for @⟦1⟧/⟦2⟧ with ⟦3⟧% weight?",
  "Голосование @⟦0⟧ за @⟦1⟧/⟦2⟧ на ⟦3⟧% отменено пользователем.": "Vote by @⟦0⟧ for @⟦1⟧/⟦2⟧ at ⟦3⟧% was canceled by the user.",
  "Аккаунт @⟦0⟧ не найден в локальном хранилище авторизации.": "Account @⟦0⟧ was not found in local authorization storage.",
  "Голос отправлен: @⟦0⟧ → @⟦1⟧/⟦2⟧, ⟦3⟧%.": "Vote submitted: @⟦0⟧ → @⟦1⟧/⟦2⟧, ⟦3⟧%.",
