  "Если у вас есть приложение, можете создать наградной фонд. Как? Награждаете свой аккаунт раз в 432 секунды на 0.1%. Вы будете получать ⟦0⟧ SHARES. Раз в сутки необходимо из соц. капитала выводить ⟦1⟧ SHARES, а для этого доступно к выводу в соц. капитале должно быть не менее ⟦2⟧ SHARES.": "If you have an app, you can create a reward fund. How? Reward your own account by 0.1% once every 432 seconds. You will receive ⟦0⟧ SHARES. Once per day, withdraw ⟦1⟧ SHARES from social capital; to do this, at least ⟦2⟧ SHARES must be available for withdrawal in social capital.",
