  "Legacy multisig подписывал JSON-транзакции client-side и отправлял signed transaction через публичную ноду. В v3 доступны static-safe helpers: настройка account auths через accountUpdate и отправка заранее подписанной transaction JSON без хранения WIF.": "Legacy multisig signed JSON transactions client-side and submitted the signed transaction through a public node. v3 provides static-safe helpers: configure account auths through accountUpdate and submit pre-signed transaction JSON without storing WIFs.",
