  "Ставим на курс криптовалют и пулов в Minter при помощи сервиса экосистемы LONG": "Bet on cryptocurrency and pool rates in Minter using the LONG ecosystem service",
  "Видео-справка по LONG ставкам на курс криптовалют и пулов Minter": "Video guide to LONG bets on cryptocurrency and Minter pool rates",
  "Статическая read-only страница: видео открываются напрямую с YouTube, без PHP, приватного backend и отправки операций.": "Static read-only page: videos open directly from YouTube, without PHP, a private backend, or operation submission.",
  "Minter справка открыта как статическая видео-страница без backend.": "Minter help opened as a static video page without a backend.",
  "Legacy VIZ help автоматически перенаправлял браузер через": "Legacy VIZ help automatically redirected the browser through",
  "на обзор сервисов dpos.space. В static v3 авто-редирект заменён явной доступной ссылкой, чтобы пользователь и screen reader не теряли контекст.": "to the dpos.space service overview. In static v3, the auto-redirect was replaced by an explicit accessible link so users and screen readers do not lose context.",
  "Обзор сервисов dpos.space на viz.media": "Overview of dpos.space services on viz.media",
  "Раздел read-only: он не отправляет операции, не вызывает PHP и не использует скрытые backend API.": "Read-only section: it does not send operations, call PHP, or use hidden backend APIs.",
  "VIZ справка открыта как явная статическая ссылка без auto-redirect.": "VIZ help opened as an explicit static link without auto-redirect.",
  "Legacy Steem help автоматически перенаправлял браузер на обзор сервисов dpos.space для Steem. В static v3 auto-redirect заменён явной доступной ссылкой, чтобы пользователь и screen reader не теряли контекст.": "Legacy Steem help automatically redirected the browser to the dpos.space service overview for Steem. In static v3, the auto-redirect was replaced with an explicit accessible link so the user and screen reader do not lose context.",
  "Обзор сервисов приложения dpos.space для блокчейна Steem": "Overview of dpos.space application services for the Steem blockchain",
  "Steem справка открыта как явная статическая ссылка без auto-redirect.": "Steem help opened as an explicit static link without auto-redirect.",
