  "Пост импортирован при помощи": "Post imported using",
  "VIZ: Импорт в Voice / readdle.me": "VIZ: Import into Voice / readdle.me",
  "Для публикации нужен выбранный VIZ-аккаунт с regular key или Vizonator. Legacy форма показывала это сообщение как": "Publishing requires a selected VIZ account with a regular key or Vizonator. The legacy form displayed this message as",
