  "и": "and",
  ", очищал HTML, загружал картинки на Imgur и публиковал custom protocol": ", sanitized HTML, uploaded images to Imgur, and published a custom protocol",
  "в Voice (": "to Voice (",
  "старый импорт использовал CORS proxy endpoint и внешний Imgur Client-ID для переноса изображений. Это backend-only non-goal в static v3: скрытый proxy, image rehosting и серверная загрузка URL не восстанавливаются; URL пробуется напрямую из браузера, а надёжный путь — вставить HTML/текст вручную.": "the old import used a CORS proxy endpoint and an external Imgur Client-ID to transfer images. This is a backend-only non-goal in static v3: the hidden proxy, image rehosting, and server-side URL loading are not restored; the URL is tried directly in the browser, and the reliable path is to paste the HTML/text manually.",
  "Подготовить черновик из URL или HTML": "Prepare draft from URL or HTML",
