  "Укажите URL или вставьте HTML/текст статьи.": "Enter a URL or paste the article HTML/text.",
  "Черновик Voice подготовлен локально. Проверьте заголовок, текст и изображения перед публикацией.": "Voice draft prepared locally. Check the title, text, and images before publishing.",
  "Если браузер заблокировал URL из-за CORS, вставьте HTML/текст вручную.": "If the browser blocked the URL because of CORS, paste the HTML/text manually.",
  "Автор Voice публикации": "Voice publication author",
  "Проверьте текст публикации: static v3 не переносит изображения через Imgur и не использует legacy CORS proxy.": "Check the publication text: static v3 does not transfer images through Imgur and does not use the legacy CORS proxy.",
  "VIZ voice-import открыт: импорт выполняется локально, публикация — через подтверждаемый custom protocol V.": "VIZ voice-import opened: import runs locally, and publication uses the confirmable custom protocol V.",
  "⟦0⟧: импорт статьи": "⟦0⟧: article import",
  "Вставьте URL или HTML/текст статьи. v3 разбирает Telegra.ph/Mirror-like HTML локально через DOMParser; произвольные URL могут не загрузиться из-за CORS, тогда вставьте HTML вручную.": "Paste the article URL or HTML/text. v3 parses Telegra.ph/Mirror-like HTML locally through DOMParser; arbitrary URLs may fail to load due to CORS, in which case paste the HTML manually.",
