  "Загружаю балансы и UIA whitelist через публичный Golos RPC...": "Loading balances and the UIA whitelist through the public Golos RPC...",
  "Токены загружены. Поля продажи/покупки можно выбрать из подсказок; максимум показан рядом.": "Tokens loaded. The sell/buy fields can be selected from suggestions; the maximum is shown nearby.",
