  "⟦0⟧ должен быть символом A-Z/0-9 длиной 2-16.": "⟦0⟧ must be a 2–16 character A–Z/0–9 symbol.",
  "Не удалось определить precision для UIA ⟦0⟧.": "Could not determine precision for UIA ⟦0⟧.",
