  "Сумма продажи": "Sell amount",
  "Не удалось найти подходящие ордера для обмена ⟦0⟧ → ⟦1⟧.": "Could not find suitable orders for exchanging ⟦0⟧ → ⟦1⟧.",
  "DEX вернул некорректный результат обмена. Проверьте токены и сумму.": "The DEX returned an invalid swap result. Check the tokens and amount.",
  "DEX не сформировал операции обмена.": "DEX did not create exchange operations.",
  "Операции сформированы через Golos DEX по текущему стакану с fill_or_kill=true. Перед отправкой проверьте JSON и результат обмена.": "Operations were formed through Golos DEX using the current order book with fill_or_kill=true. Check the JSON and exchange result before sending.",
  "У VIZ в старом коде нет ясного DEX/swap flow.": "The old VIZ code has no clear DEX/swap flow.",
  "Legacy Hive swap менял только пару HIVE/HBD: выбиралась сумма продажи, показывался расчёт покупки по стакану, режим переключался между моментальным обменом fill_or_kill=true и произвольным ордером, открытые ордера удалялись через cancel. В v3 это сохранено как static-safe формы limit order create/cancel и read-only getOrderBook/getOpenOrders через публичную ноду, без backend/service.": "Legacy Hive swap supported only the HIVE/HBD pair: users selected the sell amount, saw the estimated purchase from the order book, switched between an immediate fill_or_kill=true exchange and a regular order, and canceled open orders. v3 preserves this as static-safe limit-order create/cancel forms and read-only getOrderBook/getOpenOrders through a public node, without a backend/service.",
  "История обменов": "Exchange history",
  "Legacy Steem swap менял только пару STEEM/SBD: выбиралась сумма продажи, показывался расчёт покупки по стакану, режим переключался между моментальным обменом и произвольным ордером, открытые ордера удалялись через cancel. В v3 это сохранено как static-safe формы limit order create/cancel и read-only getOrderBook/getOpenOrders через публичную ноду, без backend/service.": "The legacy Steem swap changed only the STEEM/SBD pair: the sell amount was selected, the purchase calculation from the order book was shown, the mode switched between instant exchange and a custom order, and open orders were removed through cancel. In v3, this is preserved as static-safe limit order create/cancel forms and read-only getOrderBook/getOpenOrders through a public node, without a backend/service.",
  "⟦0⟧: маркет / обмен": "⟦0⟧: market / exchange",
  "Создание/отмена ордеров и прямой обмен по текущему стакану с подтверждением операции.": "Create/cancel orders and exchange directly against the current order book with operation confirmation.",
