  "Публичный RPC показывает текущие witness records. Исторические суммы наград из legacy backend здесь намеренно не отображаются, потому что browser-only v3 не имеет серверного индекса для таких агрегатов.": "Public RPC shows current witness records. Historical reward totals from the legacy backend are intentionally omitted because browser-only v3 has no server index for such aggregates.",
