  ", который преобразовывал form-urlencoded поля в JSON. Static v3 не восстанавливает PHP endpoint, jQuery UI drag/drop builder и вставляемый внешний скрипт; JSON проверяется локально в браузере.": ", which converted form-urlencoded fields to JSON. Static v3 does not restore the PHP endpoint, jQuery UI drag/drop builder, or inserted external script; JSON is validated locally in the browser.",
  "Отправить custom_json — preview перед broadcast": "Submit custom_json — preview before broadcast",
  "Подготовить VIZ custom_json": "Prepare VIZ custom_json",
  "Заменяет legacy действия «Получить JSON текущей формы» и «Открыть получившуюся форму»: вставьте уже готовый JSON, проверьте preview, затем отправляйте только после явного подтверждения.": "Replaces the legacy actions “Get JSON of current form” and “Open resulting form”: paste the ready-made JSON, check the preview, then send it only after explicit confirmation.",
  "Проверить JSON и операцию": "Check JSON and operation",
