  "VIZ: JSON-генератор открыт. PHP json_encode и drag/drop builder не восстанавливаются; отправка идёт через общий подтверждаемый broadcast flow.": "VIZ: JSON generator opened. PHP json_encode and the drag-and-drop builder are not restored; submission uses the shared confirmable broadcast flow.",
