  ". Это backend/indexer-only non-goal для статической v3: здесь нет скрытого сервера, не показываются вымышленные списки/проценты.": ". This is a backend/indexer-only non-goal for static v3: there is no hidden server here, and no fabricated lists/percentages are shown.",
