  ". Для известного permlink используйте форму голосования ниже.": ". For a known permlink, use the voting form below.",
  "Так как ответы и активность опроса legacy получал из backend/indexer, v3 не угадывает список вариантов. Введите известный": "Because legacy obtained poll answers and activity from a backend/indexer, v3 does not guess the option list. Enter the known",
