  "Legacy LONG строил рейтинг провайдеров, лотереи, ставки, опросы, драконов и отложенные отправки из приватного smartfarm backend и PHP-шаблонов. Static v3 не добавляет hidden server API, PHP runtime, indexer, daemon или hosted helper app.": "Legacy LONG built provider rankings, lotteries, bets, polls, dragons, and deferred submissions from a private smartfarm backend and PHP templates. Static v3 does not add a hidden server API, PHP runtime, indexer, daemon, or hosted helper app.",
  "Рейтинг провайдеров": "Provider ranking",
  "недоступен без legacy backend; показываем только проверяемый публичный пул BIP/LONG и адреса.": "is unavailable without the legacy backend; only the verifiable public BIP/LONG pool and addresses are shown.",
  "Ставки, Опросы, Лотереи, RPS, драконы, семейный калькулятор и Отложенные транзакции": "Bets, Polls, Lotteries, RPS, Dragons, Family Calculator, and Deferred Transactions",
  "требуют серверного состояния или индексированных списков. Они оставлены как документированные static-only non-goals.": "require server-side state or indexed lists. They remain documented static-only non-goals.",
  "для LONG не добавлены в этот раздел: используйте Minter кошелёк/swap только для уже поддержанных явных операций.": "for LONG are not included in this section: use the Minter wallet/swap only for explicitly supported operations.",
  "Загружаю обзор и рейтинг LONG...": "Loading LONG overview and rating...",
  "Загружаю LONG: обзор и рейтинг...": "Loading LONG: overview and ranking...",
  "Раздел показывает параметры LONG по данным активного backend": "This section shows LONG parameters from the active backend",
  "и публичной сети Minter. Это информационный расчёт: итоговые значения зависят от состояния блокчейна, ликвидности, правил сервиса и доступности backend.": "and the public Minter network. This is an informational calculation: final values depend on blockchain state, liquidity, service rules, and backend availability.",
