  "Пропущено блоков": "Missed blocks",
  "Legacy Minter validators читали публичный endpoint https://explorer-api.minter.network/api/v2/validators, делили список на «Активные валидаторы» и «Кандидаты», сортировали по stake и позволяли копировать публичный ключ. v3 делает то же без PHP/backend runtime.": "Legacy Minter validators read the public endpoint https://explorer-api.minter.network/api/v2/validators, divided the list into “Active validators” and “Candidates”, sorted by stake, and allowed the public key to be copied. v3 does the same without PHP/backend runtime.",
  "Legacy Decimal validators читали публичный endpoint https://api.decimalchain.com/api/v1/validators/validators из PHP, делили список по kind Approved/кандидаты, сортировали по stake и позволяли копировать evmAddress. v3 делает тот же read-only просмотр напрямую из браузера, без PHP/backend runtime.": "Legacy Decimal validators read the public endpoint https://api.decimalchain.com/api/v1/validators/validators from PHP, split the list by kind into Approved/candidates, sorted it by stake, and allowed copying evmAddress. v3 provides the same read-only view directly in the browser, without a PHP/backend runtime.",
