  "Поделиться backup-файлом": "Share backup file",
  "Кнопка «Поделиться» открывает системное меню Android/iOS/браузера, если оно поддерживает отправку файлов. Пароль передавайте отдельно.": "The “Share” button opens the Android/iOS/browser system menu if it supports file sharing. Send the password separately.",
  "Быстрый backup через passkey": "Quick backup with passkey",
  "Если Chrome/WebView поддерживает WebAuthn PRF, можно создать backup без ручного пароля: файл шифруется ключом, полученным из passkey после отпечатка, лица или PIN устройства. Если не сработает, используйте парольный backup выше.": "If Chrome/WebView supports WebAuthn PRF, you can create a backup without a manual password: the file is encrypted with a key derived from the passkey after fingerprint, face, or device PIN verification. If this does not work, use the password-protected backup above.",
