  "Управление блокчейном и профилем: proxy, голосование за witness, настройки witness, профиль и права доступа. Для VIZ доступны invite и committee операции.": "Blockchain and profile management: proxy, witness voting, witness settings, profile, and permissions. Invite and committee operations are available for VIZ.",
