  "Загрузить список делегаты": "Load witnesses list",
  "Если нужно изменить ключ активации, вставьте новый ключ подписи блоков в поле и нажмите «Активировать делегата». Сохранённый ключ показан под полем сокращённо и доступен кнопкой.": "If you need to change the activation key, paste the new block-signing key into the field and click “Activate witness”. The saved key is shown in abbreviated form below the field and is available via a button.",
  "URL witness / пост делегата": "URL witness / witness post",
  "Точный параметр сети: 100% энергии восстанавливается за 432000 секунд. Поэтому 0.1% восстанавливается за 7 минут 12 секунд. Внутри VIZ энергия хранится по шкале 0–10000: 9500 означает 95%, а 9900 — 99%. Web-версия работает, пока открыта страница/PWA; фоновая Android-версия доступна в APK.": "Exact network parameter: 100% of energy is restored in 432000 seconds. Therefore, 0.1% is restored in 7 minutes 12 seconds. In VIZ, energy is stored on a 0–10000 scale: 9500 means 95%, and 9900 means 99%. The web version works while the page/PWA is open; the background Android version is available in the APK.",
  "заменён public RPC getChainProperties (не требуется формулами legacy calculator)": "replaced with public RPC getChainProperties (not required by the legacy calculator formulas)",
